@startuml

class Driver {
  + firstName : string
  + lastName : string
}

class Location {
  + address : string
}

class Order {
  + executionDate : date
}

abstract class Vehicle {
  + vehicleNumber : string
}

class Truck extends Vehicle {
  + weight : float
}

class Car extends Vehicle {
  + seats : int
}

class Van extends Vehicle {}

Location "1" -- "*" Driver : has
Location "1" -- "*" Order : origin
Location "1" -- "*" Order : destination
Driver "1" -- "0..1" Order : carries out
Driver "1" -- "0..1" Order : assigned to
Driver "1" -- "0..*" Vehicle : drives

@enduml

